    "How they are paid": "Как ему платят",
    "A month that comes to less than {amount} is topped up to it — a month the company could not fill is still paid in full. A month that runs past it is paid for what was actually done; the pillow is a floor, never a bonus on top.": "Месяц, вышедший меньше {amount}, добирается до этой суммы: месяц, который компания не смогла наполнить работой, всё равно оплачивается полностью. Месяц, вышедший за неё, оплачивается по факту сделанного — подушка это пол, а не премия сверху.",
    "Nothing guaranteed. Set an amount and the month can never come to less than it.": "Ничего не гарантировано. Укажите сумму — и месяц никогда не выйдет меньше неё.",
    "Base, the per-piece rates and the bonuses — what every card did before schemes existed.": "База, поштучные ставки и бонусы — так работала любая карточка до появления схем.",
