    "{n} knock-on": "{n} по цепочке",
    "A step that could only start after its own day had gone, because the one before it handed over late. Not charged to anybody.": "Этап, который смог начаться только после своего срока, потому что предыдущий передали поздно. Никому не засчитывается.",
    "Click a month to open it": "Нажмите на месяц, чтобы открыть его",
