    "This is tidying, not permission: a page switched off leaves the sidebar and its own address for everybody, but the work behind it is still on the board and still counted.": "Это порядок, а не права: выключенная страница исчезает из меню и по своему адресу для всех, но работа за ней остаётся на доске и продолжает считаться.",
