    "It may be an older .doc rather than a .docx. The file itself is one press away.": "Возможно, это старый .doc, а не .docx. Сам файл — в одно нажатие.",
    "Excel and PowerPoint open in their own app. Everything about it is above — the file itself is one press away.": "Excel и PowerPoint открываются в своём приложении. Всё о файле — выше, а сам файл в одно нажатие.",
