    "How they are paid": "Unga qanday toʻlanadi",
    "A month that comes to less than {amount} is topped up to it — a month the company could not fill is still paid in full. A month that runs past it is paid for what was actually done; the pillow is a floor, never a bonus on top.": "{amount} dan kam chiqqan oy shu summagacha toʻldiriladi: kompaniya ish bilan toʻldira olmagan oy ham toʻliq toʻlanadi. Undan oshib ketgan oy qilingan ish boʻyicha toʻlanadi — yostiq bu poydevor, ustiga qoʻshiladigan mukofot emas.",
