    "A band of skip rate, and what a piece in it pays. Lower skip is better. A piece nobody has measured is in no band and adds nothing — it is not the worst one.": "Tashlab ketish foizi oraligʻi va undagi material qancha toʻlashi. Foiz kamroq boʻlgani yaxshi. Oʻlchanmagan material hech qaysi oraliqqa tushmaydi va hech nima qoʻshmaydi — u «eng yomoni» emas.",
