    "Download .md": ".md yuklab olish",
    "Pages opened, where people pressed and what the board said no with, by name — never what anybody typed. Read \"What to improve first\" at the top.": "Ochilgan sahifalar, bosishlar va doska rad etgan narsalar — ism bilan, lekin hech kim yozgan narsa emas. Yuqoridagi «What to improve first» boʻlimidan boshlang.",
    "See where people pressed:": "Qayerni bosishgan:",
